size_t N = 5;
int* array;

// Allocate N integers dynamically
array = (int*)malloc(N * sizeof(int));

if (array == NULL) {
    // Allocation failed
    return;
}

// Access allocated memory
for (size_t i = 0; i < N; i++) {
    array[i] = (int)i * 2;
}

// Release the memory block when done
free(array);

// Example for struct allocation
typedef struct { int x; } Point;
Point* p = (Point*)malloc(sizeof(Point));
p->x = 10;
free(p);
